async function sendStartMessage(ctx) {
    upsertTelegramUser(ctx);
    return safeReply(ctx, buildStartMessage(ctx), getStartKeyboard());
}

bot.start(async (ctx) => {
    if (!(await ensureSubscription(ctx))) return;
    await sendStartMessage(ctx);
});


